package nl.smartstreamlabs.sbwdroneconfig;
import com.google.gson.*;import net.minecraft.core.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;import java.util.*;import java.io.*;
/** Offline solid-mesh shapes. Flat variant indices encode damage even when the controller chunk is absent. */
public final class Pb01Geometry{
 public static final Pb01Geometry MODEL=new Pb01Geometry();public record Variant(int[]cell,int mask){}public record Part(int bone,int zone,int category){}
 public final List<AABB>[]zones,leaf;public final Variant[]bodyVariants,doorVariants;public final int[][]body,door,support,lamps;public final int[]bodyBase,doorBase;public final double[][]seats;public final double[]hinge;public final AABB bounds,doorBounds;public final List<Part>parts=new ArrayList<>();public final List<AdcGeometry.Bone>bones=new ArrayList<>();public final Map<String,Integer>names=new HashMap<>();private final Map<String,Integer>lookup=new HashMap<>();
 private final Map<Long,VoxelShape>shapes=Collections.synchronizedMap(new LinkedHashMap<>(256,.75f,true){@Override protected boolean removeEldestEntry(Map.Entry<Long,VoxelShape>e){return size()>8192;}});
 private Pb01Geometry(){try(var r=new InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("/assets/sbwdroneconfig/pb01/collision.json")))){var j=JsonParser.parseReader(r).getAsJsonObject();body=ints(j.getAsJsonArray("body"));door=ints(j.getAsJsonArray("door_cells"));support=ints(j.getAsJsonArray("support"));lamps=ints(j.getAsJsonArray("lamps"));bodyBase=values(j.getAsJsonArray("body_base"));doorBase=values(j.getAsJsonArray("door_base"));bodyVariants=variants(j.getAsJsonArray("body_variants"),false);doorVariants=variants(j.getAsJsonArray("door_variants"),true);seats=points(j.getAsJsonArray("seats"));hinge=point(j.getAsJsonArray("hinge"));bounds=box(j.getAsJsonArray("bounds"));doorBounds=box(j.getAsJsonArray("door_bounds"));zones=new List[16];leaf=new List[22];for(int i=0;i<16;i++)zones[i]=boxes(j.getAsJsonArray("zones").get(i).getAsJsonArray());for(int i=0;i<22;i++)leaf[i]=boxes(j.getAsJsonArray("door").get(i).getAsJsonArray());try(var m=new InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("/assets/sbwdroneconfig/pb01/pb01.json")))){var g=JsonParser.parseReader(m).getAsJsonObject();for(var v:g.getAsJsonArray("bones")){var b=v.getAsJsonObject();names.put(b.get("name").getAsString(),bones.size());var p=point(b.getAsJsonArray("pivot"));var a=point(b.getAsJsonArray("rotation"));bones.add(new AdcGeometry.Bone(b.get("name").getAsString(),b.get("parent").getAsInt(),new org.joml.Vector3d(p),new org.joml.Vector3d(a)));}for(var v:g.getAsJsonArray("parts")){var p=v.getAsJsonObject();parts.add(new Part(p.get("bone").getAsInt(),p.get("zone").getAsInt(),p.get("category").getAsInt()));}}}catch(IOException e){throw new ExceptionInInitializerError(e);}}
 private Variant[]variants(JsonArray a,boolean moving){var out=new Variant[a.size()];for(int i=0;i<out.length;i++){var o=a.get(i).getAsJsonObject();var c=values(o.getAsJsonArray("cell"));int mask=o.get("mask").getAsInt();out[i]=new Variant(c,mask);lookup.put(key(c,mask,moving),i);}return out;}
 private static String key(int[]c,int mask,boolean moving){return moving+":"+c[0]+","+c[1]+","+c[2]+":"+mask;}
 public int variant(boolean moving,int base,int broken){var v=(moving?doorVariants:bodyVariants)[base];return lookup.get(key(v.cell,v.mask&~broken,moving));}
 public Variant variant(boolean moving,int part){var a=moving?doorVariants:bodyVariants;return a[Math.max(0,Math.min(a.length-1,part))];}
 private static int[]values(JsonArray a){int[]r=new int[a.size()];for(int i=0;i<r.length;i++)r[i]=a.get(i).getAsInt();return r;}private static int[][]ints(JsonArray a){int[][]r=new int[a.size()][];for(int i=0;i<r.length;i++)r[i]=values(a.get(i).getAsJsonArray());return r;}private static double[]point(JsonArray a){double[]r=new double[a.size()];for(int i=0;i<r.length;i++)r[i]=a.get(i).getAsDouble();return r;}private static double[][]points(JsonArray a){double[][]r=new double[a.size()][];for(int i=0;i<r.length;i++)r[i]=point(a.get(i).getAsJsonArray());return r;}private static AABB box(JsonArray a){var b=point(a);return new AABB(b[0],b[1],b[2],b[3],b[4],b[5]);}private static List<AABB>boxes(JsonArray a){var r=new ArrayList<AABB>();for(var b:a)r.add(box(b.getAsJsonArray()));return List.copyOf(r);}
 public static Vec3 point(BlockPos root,Direction f,double x,double y,double z){return Ps01Geometry.point(root,f,x,y,z);}public static Vec3 local(BlockPos root,Direction f,Vec3 p){return Ps01Geometry.local(root,f,p);}public static BlockPos cell(BlockPos root,Direction f,int[]c){return Ps01Geometry.cell(root,f,c);}public static AABB box(BlockPos root,Direction f,AABB b){return Ps01Geometry.box(root,f,b);}public AABB bounds(BlockPos p,Direction f){return box(p,f,bounds);}
 public VoxelShape shape(Direction face,boolean moving,int part,int step){long key=(((long)part*4+face.get2DDataValue())*2+(moving?1:0))*22+Math.max(0,Math.min(21,step));var cached=shapes.get(key);if(cached!=null)return cached;var v=variant(moving,part);var p=cell(BlockPos.ZERO,face,v.cell);var s=Shapes.empty();for(int i=0;i<16;i++)if((v.mask&(1<<i))!=0)for(var b:i==10?leaf[Math.max(0,Math.min(21,step))]:zones[i]){var w=box(BlockPos.ZERO,face,b);double x=Math.max(0,w.minX-p.getX()),y=Math.max(0,w.minY-p.getY()),z=Math.max(0,w.minZ-p.getZ()),X=Math.min(1,w.maxX-p.getX()),Y=Math.min(1,w.maxY-p.getY()),Z=Math.min(1,w.maxZ-p.getZ());if(X>x&&Y>y&&Z>z)s=Shapes.or(s,Shapes.box(x,y,z,X,Y,Z));}s=s.optimize();shapes.put(key,s);return s;}
 public boolean lamp(int[]c){for(var a:lamps)if(Arrays.equals(a,c))return true;return false;}
 public List<BlockPos>all(BlockPos p,Direction f){var r=new ArrayList<BlockPos>();for(var c:body)r.add(cell(p,f,c));for(var c:door)r.add(cell(p,f,c));return r;}
 public List<AABB>material(int zone,int step){return zone==10?leaf[Math.max(0,Math.min(21,step))]:zones[zone];}
 public static boolean intersects(List<AABB>boxes,Vec3 a,Vec3 b){return Ps01Geometry.intersects(boxes,a,b);}
 public int hitZone(Vec3 p,int mask,int step){for(int i:new int[]{10,9,1,2,3,4,5,6,7,8,0,12,11,13,14,15})if((mask&(1<<i))!=0)for(var b:material(i,step))if(b.inflate(.065).contains(p))return i;return -1;}
 public double cover(Vec3 a,Vec3 b,int mask,int step,double[]integrity,boolean blast){double best=0;for(int i=0;i<16;i++)if((i<=10||i==14)&&(mask&(1<<i))!=0&&intersects(material(i,step),a,b)){double factor=i==10?(blast?Pb01Config.DOOR_BLAST.get():Pb01Config.DOOR_FRAGMENT.get()):(blast?Pb01Config.BLAST.get():Pb01Config.FRAGMENT.get());best=Math.max(best,factor*Math.sqrt(Math.max(0,integrity[i])));}return best;}
 public Vec3 anchor(BlockPos p,Direction f,String name){var a=bones.get(names.get(name)).pivot();return point(p,f,a.x,a.y,a.z);}
 public org.joml.Matrix4f pose(int bone,float progress){var b=bones.get(bone);var m=b.parent()<0?new org.joml.Matrix4f():pose(b.parent(),progress);if(b.name().equals("Door_Leaf")){var a=b.pivot();m.translate((float)a.x,(float)a.y,(float)a.z).rotateY((float)Math.toRadians(-105*progress)).translate((float)-a.x,(float)-a.y,(float)-a.z);}return m;}
}
